// ignore_for_file: avoid_print

import 'dart:convert';
import 'dart:io';

const _header =
    '// Generated by tool/generate_admin.dart from spec/. Do not edit.\n';
final _priced = RegExp('cost|price', caseSensitive: false);
const _reserved = {
  'abstract',
  'as',
  'assert',
  'async',
  'await',
  'break',
  'case',
  'catch',
  'class',
  'const',
  'continue',
  'covariant',
  'default',
  'deferred',
  'do',
  'dynamic',
  'else',
  'enum',
  'export',
  'extends',
  'extension',
  'external',
  'factory',
  'false',
  'final',
  'finally',
  'for',
  'Function',
  'get',
  'hide',
  'if',
  'implements',
  'import',
  'in',
  'interface',
  'is',
  'late',
  'library',
  'mixin',
  'new',
  'null',
  'on',
  'operator',
  'part',
  'required',
  'rethrow',
  'return',
  'sealed',
  'set',
  'show',
  'static',
  'super',
  'switch',
  'sync',
  'this',
  'throw',
  'true',
  'try',
  'typedef',
  'var',
  'void',
  'when',
  'while',
  'with',
  'yield',
};

Map<String, Object?> _map(Object? value) =>
    value is Map<String, Object?> ? value : const {};

List<Object?> _list(Object? value) => value is List<Object?> ? value : const [];

Object? _withoutPrices(Object? node) {
  // [1] Traverse nested schema fragments before selecting response models.
  if (node is List<Object?>) return node.map(_withoutPrices).toList();
  if (node is! Map<String, Object?>) return node;
  final copy = <String, Object?>{};
  // [2] Remove priced properties and their required entries together.
  for (final entry in node.entries) {
    if (entry.key == 'properties') {
      copy[entry.key] = <String, Object?>{
        for (final property in _map(entry.value).entries)
          if (!_priced.hasMatch(property.key))
            property.key: _withoutPrices(property.value),
      };
    } else if (entry.key == 'required') {
      copy[entry.key] = [
        for (final name in _list(entry.value))
          if (name is String && !_priced.hasMatch(name)) name,
      ];
    } else {
      copy[entry.key] = _withoutPrices(entry.value);
    }
  }
  return copy;
}

void _references(Object? node, Set<String> names) {
  // [1] Walk arrays and objects for schema references.
  if (node is List<Object?>) {
    for (final value in node) {
      _references(value, names);
    }
  } else if (node is Map<String, Object?>) {
    // [2] Record a reference before following its nested values.
    final ref = node[r'$ref'];
    if (ref is String && ref.startsWith('#/components/schemas/')) {
      names.add(ref.substring('#/components/schemas/'.length));
    }
    for (final value in node.values) {
      _references(value, names);
    }
  }
}

String? _refName(Map<String, Object?> schema) {
  final ref = schema[r'$ref'];
  if (ref is String && ref.startsWith('#/components/schemas/')) {
    return ref.substring('#/components/schemas/'.length);
  }
  return null;
}

Map<String, Object?> _nonNull(Map<String, Object?> schema) {
  final oneOf = _list(schema['oneOf']);
  if (oneOf.isNotEmpty) {
    for (final item in oneOf) {
      final candidate = _map(item);
      if (candidate['type'] != 'null') return candidate;
    }
  }
  final type = schema['type'];
  if (type is List<Object?>) {
    return {...schema, 'type': type.firstWhere((t) => t != 'null')};
  }
  return schema;
}

bool _nullable(Map<String, Object?> schema) =>
    _list(schema['oneOf']).any((item) => _map(item)['type'] == 'null') ||
    _list(schema['type']).contains('null');

String _type(Map<String, Object?> schema, Map<String, Object?> schemas) {
  // [1] Resolve references to either another object model or a primitive.
  final value = _nonNull(schema);
  final ref = _refName(value);
  if (ref != null) {
    final target = _map(schemas[ref]);
    return target['type'] == 'object' || target.containsKey('properties')
        ? ref
        : _type(target, schemas);
  }
  // [2] Map supported OpenAPI shapes to Dart getter types.
  switch (value['type']) {
    case 'string':
      return 'String';
    case 'integer':
      return 'int';
    case 'number':
      return 'num';
    case 'boolean':
      return 'bool';
    case 'array':
      return 'List<${_type(_map(value['items']), schemas)}>';
    case 'object':
      return 'Map<String, Object?>';
    default:
      return 'Object?';
  }
}

String _validExpression(
    String value, Map<String, Object?> schema, Map<String, Object?> schemas) {
  // [1] Validate referenced objects recursively.
  final shape = _nonNull(schema);
  final ref = _refName(shape);
  if (ref != null) {
    final target = _map(schemas[ref]);
    if (target['type'] == 'object' || target.containsKey('properties')) {
      return '$ref.isValid($value)';
    }
    return _validExpression(value, target, schemas);
  }
  // [2] Validate primitives and every array element.
  switch (shape['type']) {
    case 'string':
      return '$value is String';
    case 'integer':
      return '$value is int';
    case 'number':
      return '$value is num';
    case 'boolean':
      return '$value is bool';
    case 'object':
      return '$value is Map<String, Object?>';
    case 'array':
      final item = _validExpression('item', _map(shape['items']), schemas);
      return '$value is List<Object?> && $value.every((item) => $item)';
    default:
      return 'true';
  }
}

String _getterExpression(
    String value, Map<String, Object?> schema, Map<String, Object?> schemas,
    {bool promoted = false}) {
  // [1] Wrap referenced objects in their generated extension types.
  final shape = _nonNull(schema);
  final ref = _refName(shape);
  if (ref != null) {
    final target = _map(schemas[ref]);
    if (target['type'] == 'object' || target.containsKey('properties')) {
      return '$ref._(${promoted ? value : '$value as Map<String, Object?>'})';
    }
    return _getterExpression(value, target, schemas, promoted: promoted);
  }
  // [2] Convert arrays and scalar values without widening the wire type.
  if (shape['type'] == 'array') {
    final itemSchema = _map(shape['items']);
    final itemType = _type(itemSchema, schemas);
    final convert = _getterExpression('item', itemSchema, schemas);
    final list = promoted ? value : '($value as List<Object?>)';
    return '$list.map<$itemType>((item) => $convert).toList()';
  }
  final type = _type(shape, schemas);
  return type == 'Object?' || promoted ? value : '$value as $type';
}

String _lowerCamel(String name) {
  final parts = name.split('_');
  final value = parts.first +
      parts
          .skip(1)
          .map((part) =>
              part.isEmpty ? '' : part[0].toUpperCase() + part.substring(1))
          .join();
  return _reserved.contains(value) ? '${value}Value' : value;
}

String _model(
    String name, Map<String, Object?> schema, Map<String, Object?> schemas) {
  // [1] Start one documented extension type for a reachable object schema.
  final out = StringBuffer();
  final description = (schema['description'] as String?)?.split('\n').first;
  out.writeln(
      '/// ${description?.isNotEmpty == true ? description : 'A $name response.'}');
  out.writeln('extension type $name._(Map<String, Object?> json) {');
  final properties = _map(schema['properties']);
  final required = _list(schema['required']).whereType<String>().toSet();
  // [2] Emit safe optional getters and direct required getters.
  for (final entry in properties.entries) {
    final property = _map(entry.value);
    final type = _type(property, schemas);
    final getterName = _lowerCamel(entry.key);
    final isNullable = !required.contains(entry.key) || _nullable(property);
    final value = "json['${entry.key}']";
    out.writeln('  /// The `${entry.key}` field.');
    if (isNullable) {
      final convert =
          _getterExpression('value', property, schemas, promoted: true);
      final shape = _nonNull(property);
      final ref = _refName(shape);
      final patternType = ref != null &&
              (_map(schemas[ref])['type'] == 'object' ||
                  _map(schemas[ref]).containsKey('properties'))
          ? 'Map<String, Object?>'
          : shape['type'] == 'array'
              ? 'List<Object?>'
              : type;
      final pattern =
          type == 'Object?' ? 'final value' : 'final $patternType value';
      String guard = '';
      if (ref != null && patternType == 'Map<String, Object?>') {
        guard = ' when $ref.isValid(value)';
      } else if (shape['type'] == 'array') {
        final itemValid =
            _validExpression('item', _map(shape['items']), schemas);
        guard = ' when value.every((Object? item) => $itemValid)';
      }
      out.writeln('  ${type == 'Object?' ? type : '$type?'} get $getterName => '
          'switch ($value) { $pattern$guard => $convert, _ => null };');
    } else {
      out.writeln('  $type get $getterName => '
          '${_getterExpression(value, property, schemas)};');
    }
  }
  // [3] Validate every required field, including nested objects and arrays.
  out.writeln(
      '  /// Whether the required wire fields have their expected shapes.');
  out.writeln('  static bool isValid(Object? value) {');
  out.writeln('    if (value is! Map<String, Object?>) return false;');
  for (final field in required) {
    final property = _map(properties[field]);
    final value = "value['$field']";
    final valid = _validExpression('fieldValue', property, schemas);
    out.writeln("    if (!value.containsKey('$field')) return false;");
    if (valid != 'true') {
      out.writeln('    { final fieldValue = $value;');
      final shape = _nonNull(property);
      if (shape['type'] == 'array') {
        final itemValid =
            _validExpression('item', _map(shape['items']), schemas);
        out.writeln('    if (fieldValue is! List<Object?>) { return false; }');
        out.writeln('    if (!fieldValue.every((Object? item) => $itemValid)) '
            '{ return false; }');
      } else {
        final invalid = valid.startsWith('fieldValue is ')
            ? valid.replaceFirst('fieldValue is ', 'fieldValue is! ')
            : '!($valid)';
        out.writeln(
            '    if (${_nullable(property) ? 'fieldValue != null && ' : ''}'
            '$invalid) { return false; }');
      }
      out.writeln('    }');
    }
  }
  // [4] Expose one parser that returns null for an invalid response shape.
  out.writeln('    return true;');
  out.writeln('  }');
  out.writeln('  /// Parse a valid wire object, or return null.');
  out.writeln('  static $name? tryParse(Object? value) => '
      'isValid(value) ? $name._(value as Map<String, Object?>) : null;');
  out.writeln('}');
  return out.toString();
}

Future<void> main(List<String> args) async {
  // [1] Filter price and cost properties before discovering response models.
  final root = Directory('../../spec');
  final admin = _map(_withoutPrices(
      jsonDecode(File('${root.path}/meridian-admin.json').readAsStringSync())));
  final source =
      _map(jsonDecode(File('${root.path}/SOURCE.json').readAsStringSync()));
  final schemas = _map(_map(admin['components'])['schemas']);
  final selected = <String>{};
  var operations = 0;
  for (final path in _map(admin['paths']).values) {
    for (final operation in _map(path).values) {
      final op = _map(operation);
      final security = _list(op['security']);
      if (!security.any((item) => _map(item).containsKey('IntegratorKey'))) {
        continue;
      }
      operations++;
      _references(op['responses'], selected);
    }
  }
  if (operations != 24) {
    throw StateError('Expected 24 IntegratorKey operations; found $operations');
  }
  final pending = selected.toList();
  for (var i = 0; i < pending.length; i++) {
    final before = selected.length;
    _references(schemas[pending[i]], selected);
    if (selected.length != before) {
      pending.addAll(selected.where((name) => !pending.contains(name)));
    }
  }

  // [2] Emit only reachable object schemas and the pinned version constants.
  final modelText = StringBuffer(_header);
  for (final name in selected.toList()..sort()) {
    final schema = _map(schemas[name]);
    if (schema['type'] == 'object' || schema.containsKey('properties')) {
      modelText.writeln(_model(name, schema, schemas));
    }
  }
  final versionText = '$_header/// The current Meridian package version.\n'
      "const meridianVersion = '0.0.0';\n"
      '/// The pinned engine specification revision.\n'
      "const engineSpecCommit = '${source['engineCommit']}';\n"
      '/// The pinned public engine API version.\n'
      "const engineApiVersion = '${source['publicVersion']}';\n";
  final outputs = <String, String>{
    'lib/src/generated/admin_models.dart': modelText.toString(),
    'lib/src/version.dart': versionText,
  };
  final stale = <String>[];
  for (final entry in outputs.entries) {
    final file = File(entry.key);
    final formatted = await _format(entry.value);
    if (args.contains('--check')) {
      if (!file.existsSync() || file.readAsStringSync() != formatted) {
        stale.add(entry.key);
      }
    } else {
      file.parent.createSync(recursive: true);
      file.writeAsStringSync(formatted);
    }
  }
  if (stale.isNotEmpty) {
    stderr.writeln('Generated files are stale: ${stale.join(', ')}');
    exitCode = 1;
  } else if (!args.contains('--check')) {
    print('Generated admin models and version written.');
  }
}

Future<String> _format(String content) async {
  final temporary = File('tool/.admin_format.dart');
  try {
    temporary.writeAsStringSync(content);
    final result = await Process.run('dart', ['format', temporary.path]);
    if (result.exitCode != 0) {
      throw StateError('dart format failed: ${result.stderr}');
    }
    return temporary.readAsStringSync().replaceAll('\r\n', '\n');
  } finally {
    if (temporary.existsSync()) temporary.deleteSync();
  }
}
